#!/usr/bin/env python3
"""Bounded public research captures, with exact source metadata and compressed bytes."""
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
import datetime,gzip,hashlib,json,requests,subprocess,tempfile
ROOT=Path(__file__).resolve().parent
URLS={'wibw-results': 'https://www.wibw.com/politics/election-results/', 'kcur-primary': 'https://www.kcur.org/politics-elections-and-government/2026-08-04/kansas-election-results-amendments-primary-august-2026', 'kmbc-primary': 'https://www.kmbc.com/article/august-4-primary-election-results-kansas/73299170', 'npr-primary': 'https://apps.npr.org/primary-election-results-2026/states/KS.html', 'sos-dates': 'https://www.sos.ks.gov/elections/important-election-dates.html', 'sos-calendar': 'https://www.sos.ks.gov/Pubs/Elections/Elections-201.pdf', 'sos-results': 'https://www.sos.ks.gov/elections/election-results.html', 'nyt-elections': 'https://www.nytimes.com/section/politics/elections', 'kwch-home': 'https://www.kwch.com/', 'ksn-home': 'https://www.ksn.com/', 'kake-home': 'https://www.kake.com/', 'kcur-ap-embed': 'https://interactives.apelections.org/election-results/customers/layouts/organization-layouts/published/47881/31490.html', 'kmbc-primary-embed': 'https://ehub.htvapps.com/kmbc/wp-json/election-hub/v1/iframe-embed/1754', 'kmbc-primary-widget': 'https://ehub.htvapps.com/kmbc/wp-json/election-hub/v1/widget/1754', 'sos-advance-oct14': 'https://sos.ks.gov/media/press-releases/2026/10-14-26-secretary-schwab-announces-the-start-of-advance-voting.html', 'sos-newsletters': 'https://sos.ks.gov/media/newsletters.html', 'kake-elections': 'https://www.kake.com/news/elections', 'npr-senate-primary': 'https://apps.npr.org/primary-election-results-2026/data/KS_S_8_4_2026.json', 'npr-senate-primary-counties': 'https://apps.npr.org/primary-election-results-2026/data/KS_S_8_4_2026_counties.json', 'sos-2024-president-county': 'https://www.sos.ks.gov/elections/24elec/2024-Presidential-Results.xlsx', 'sos-2024-general-canvass': 'https://www.sos.ks.gov/elections/24elec/2024-General-Election-Official-Vote-Totals.pdf', 'sos-2024-president-precinct': 'https://www.sos.ks.gov/elections/24elec/2024-General-Election-President-Precinct-Level-Results.xlsx', 'sos-2022-general-canvass': 'https://www.sos.ks.gov/elections/22elec/2022-General-Official-Vote-Totals.pdf', 'sos-2022-senate-precinct': 'https://www.sos.ks.gov/elections/22elec/2022-General-Election-US-Senate-Results-By-Precinct.xlsx', 'sos-2020-general-canvass': 'https://www.sos.ks.gov/elections/20elec/2020_General_Official_Vote_Totals.pdf', 'sos-2020-senate-precinct': 'https://www.sos.ks.gov/elections/20elec/2020_General_Election_US_Senate_results_by_precinct.xlsx', 'sos-2026-primary-canvass': 'https://www.sos.ks.gov/elections/26elec/2026-Primary-Election-Official-Vote-Totals.pdf', 'sos-2026-senate-primary-precinct': 'https://www.sos.ks.gov/elections/26elec/2026-Primary-Election-United-States-Senate-Precinct-Level-Results.xlsx', 'russell-current-mail-return': 'https://russellcountykansas.com/322/Advance-Voting-by-Mail', 'ag-july-grace-injunction': 'https://www.ag.ks.gov/Home/Components/News/News/342/1292', 'ag-july-emergency-refusal': 'https://www.ag.ks.gov/Home/Components/News/News/344/1292', 'reflector-october-grace-appeal': 'https://kansasreflector.com/2026/10/07/appeals-court-kansas-mail-in-ballots-will-be-accepted-for-three-days-after-november-election/', 'reflector-july-grace-appeal': 'https://kansasreflector.com/2026/07/31/kansas-supreme-court-declines-to-take-emergency-appeal-of-election-law/', 'sos-june-scotus-response': 'https://sos.ks.gov/media/press-releases/2026/06-29-26-schwab-issues-statement-on-scotus-ruling.html', 'legislature-sb4-summary': 'https://www.kslegislature.gov/li/b2025_26/measures/documents/summary_sb_4_2025', 'sumner-2022-county-summary-candidate': 'https://webgen1files1.revize.com/sumnercountryks/Documents/Elected%20Officials/County%20Clerk%20and%20Election%20Officer/Election%20Results/official%20election%20summary%20w%20writeins.pdf', 'sumner-county-home': 'https://co.sumner.ks.us/', 'sumner-election-office': 'https://co.sumner.ks.us/elected_officials/county_clerk_and_election_officer/election_office/index.php', 'sumner-archive': 'https://co.sumner.ks.us/elected_officials/county_clerk_and_election_officer/election_results.php', 'sumner-2022-actual-linked-summary': 'https://co.sumner.ks.us/Documents/Elected Officials/County Clerk and Election Officer/Election Results/official election summary w writeins.pdf?t=202309010533350', 'hayspost-2026-ellis-primary': 'https://hayspost.com/posts/f6d38eff-ccb7-4384-b582-f295e756310f', 'westernkansasnews-home': 'https://www.westernkansasnews.com/', 'wichita-eagle-election-index': 'https://www.kansas.com/news/politics-government/election/'}
def fetch(item):
 key,url=item;row={'id':key,'url':url,'retrieved_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
 try:
  r=requests.get(url,timeout=35);path=ROOT/(key+'.html.gz');path.write_bytes(gzip.compress(r.content,mtime=0))
  row.update(status=r.status_code,final_url=r.url,raw_sha256=hashlib.sha256(r.content).hexdigest(),asset=path.name,stored_sha256=hashlib.sha256(path.read_bytes()).hexdigest(),bytes=len(r.content),headers=dict(r.headers))
 except requests.exceptions.SSLError as e:
  row['requests_error']=str(e)
  with tempfile.TemporaryDirectory() as t:
   body=Path(t)/'body';hdr=Path(t)/'headers'
   c=subprocess.run(['curl','--silent','--show-error','--location','--max-time','35','--dump-header',str(hdr),'--output',str(body),'--write-out','%{http_code}\\n%{url_effective}',url],capture_output=True,text=True)
   row['transport']='system curl with default certificate verification'
   if c.returncode==0:
    code,final=c.stdout.split('\\n',1) if '\\n' in c.stdout else c.stdout.split('\n',1)
    raw=body.read_bytes();path=ROOT/(key+'.html.gz');path.write_bytes(gzip.compress(raw,mtime=0))
    row.update(status=int(code),final_url=final,raw_sha256=hashlib.sha256(raw).hexdigest(),asset=path.name,stored_sha256=hashlib.sha256(path.read_bytes()).hexdigest(),bytes=len(raw),raw_headers=hdr.read_text())
   else:row['error']=c.stderr
 except requests.RequestException as e:row['error']=str(e)
 return row
if __name__=='__main__':
 rows=list(ThreadPoolExecutor(max_workers=4).map(fetch,URLS.items()));(ROOT/'manifest.json').write_text(json.dumps(rows,indent=2)+'\n')
 for r in rows:print(r['id'],r.get('status',r.get('error')))
